def get_pairs_count(arr, target_sum, n):
    # Create a dictionary to store the frequency of each element in the array
    freq = {}

    # Iterate through the array and populate the frequency dictionary
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    count = 0
    # Iterate through the array again to check for pairs that add up to the target sum
    for i in range(n):
        for j in range(i+1, n):
            if (arr[i] + arr[j]) == target_sum:
                count += 1

    return count

