def find_Diff(arr, n):
    # Create an empty dictionary to store frequency of each element
    freq = {}

    # Count the frequency of each element in the array
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize variables to keep track of maximum and minimum frequencies
    max_freq = -float('inf')
    min_freq = float('inf')

    # Find the maximum and minimum frequencies
    for freq_val in freq.values():
        if freq_val > max_freq:
            max_freq = freq_val
        if freq_val < min_freq:
            min_freq = freq_val

    # Calculate the difference between the maximum and minimum frequencies
    diff = max_freq - min_freq

    return diff

